<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { ClipboardCheck, Plus, X, CalendarDays, BookOpenCheck } from '@lucide/vue'
import api from '../api'
import TeacherAttendanceSidebar from '../components/TeacherAttendanceSidebar.vue'
import { useLocaleStore } from '../stores/locale'
const locale=useLocaleStore(); const loading=ref(true); const saving=ref(false); const open=ref(false); const error=ref(''); const exams=ref<any[]>([]); const meta=ref<any>({});
const form=reactive({title:'',subject_id:'',exam_date:new Date().toISOString().slice(0,10),total_marks:100,notes:''})
async function load(){loading.value=true;try{const [dash,list]=await Promise.all([api.get('/dashboard'),api.get('/examinations')]);meta.value=dash.data;exams.value=list.data.exams}finally{loading.value=false}}
function reset(){form.title='';form.subject_id='';form.exam_date=new Date().toISOString().slice(0,10);form.total_marks=100;form.notes='';error.value=''}
async function create(){saving.value=true;error.value='';try{await api.post('/examinations',form);open.value=false;reset();await load()}catch(e:any){error.value=e?.response?.data?.message||locale.tr('Unable to create exam.')}finally{saving.value=false}}
onMounted(load)
</script>
<template><div class="app-shell teacher-shell"><TeacherAttendanceSidebar/><main class="dashboard-main"><header><div><span class="eyebrow">{{locale.tr('TEACHER WORKSPACE')}}</span><h1>{{locale.tr('Exams & marks')}}</h1></div><button class="button primary" @click="open=true"><Plus/>{{locale.tr('Create exam')}}</button></header><div class="dashboard-content teacher-content"><section class="teacher-page-head"><div><span>{{meta.branch?.name_en||meta.branch?.name_ar}}</span><h1>{{locale.tr('Exams & marks')}}</h1><p>{{locale.tr('Create assessments and enter student marks.')}}</p></div><button class="button primary" @click="open=true"><Plus/>{{locale.tr('Create exam')}}</button></section><div v-if="loading" class="loading-state"><span></span>{{locale.tr('Loading exams…')}}</div><section v-else-if="exams.length" class="teacher-card exam-list"><article v-for="exam in exams" :key="exam.public_id" class="exam-row"><span class="exam-icon"><ClipboardCheck/></span><div><b>{{exam.title}}</b><small>{{exam.subject?.name_en||exam.subject?.name_ar||locale.tr('All subjects')}} · {{exam.exam_date}}</small></div><strong>{{exam.total_marks}} {{locale.tr('marks')}}</strong><em :class="exam.status">{{exam.status}}</em></article></section><section v-else class="teacher-card teacher-list-empty"><ClipboardCheck/><h2>{{locale.tr('No assessments yet')}}</h2><p>{{locale.tr('Create an exam, choose its subject and teaching groups, then enter marks with a keyboard-friendly workflow.')}}</p><button class="button primary" @click="open=true"><Plus/>{{locale.tr('Create first exam')}}</button></section></div></main></div><div v-if="open" class="modal-backdrop" @click.self="open=false"><section class="centre-modal exam-modal" role="dialog" aria-modal="true"><button class="modal-close" @click="open=false"><X/></button><span class="modal-icon"><BookOpenCheck/></span><span class="eyebrow">{{locale.tr('NEW EXAM')}}</span><h2>{{locale.tr('Create an exam')}}</h2><p>{{locale.tr('Set the assessment details before entering marks.')}}</p><form @submit.prevent="create"><label>{{locale.tr('Exam title')}}<input v-model="form.title" required :placeholder="locale.tr('e.g. Midterm Physics')"></label><label>{{locale.tr('Subject')}}<select v-model="form.subject_id"><option value="">{{locale.tr('All subjects')}}</option><option v-for="subject in meta.subjects||[]" :key="subject.id" :value="subject.id">{{subject.name_en||subject.name_ar}}</option></select></label><div class="modal-grid"><label>{{locale.tr('Exam date')}}<input v-model="form.exam_date" type="date" required></label><label>{{locale.tr('Total marks')}}<input v-model.number="form.total_marks" type="number" min="1" required></label></div><label>{{locale.tr('Notes')}}<textarea v-model="form.notes" rows="3"></textarea></label><div v-if="error" class="form-error">{{error}}</div><div class="modal-actions"><button type="button" class="button secondary" @click="open=false">{{locale.tr('Cancel')}}</button><button class="button primary" :disabled="saving">{{saving?locale.tr('Saving…'):locale.tr('Create exam')}}<Plus/></button></div></form></section></div></template>
